(()=>{'use strict';
let config,epoch=0,detailEpoch=0,rows=[],page=1;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={active:'Active login',not_activated:'Not activated',disabled:'Login disabled',review:'Needs review'};
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((Number(v)||0)/100);
const date=v=>v?new Date(v).toLocaleString('en-US',{timeZone:'America/New_York'}):'Never';
const table=(headers,items)=>`<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${items.join('')||`<tr><td colspan="${headers.length}">No records.</td></tr>`}</tbody></table></div>`;
function clear(){epoch++;detailEpoch++;rows=[];config=null;$('panel-accounts')?.replaceChildren();}
function init(options){clear();if(options.user?.role!=='owner')return;config=options;
 const nav=document.querySelector('#dashNav [data-panel="accounts"]');if(nav)nav.onclick=()=>{options.showPanel('accounts');load()};
 if($('panel-accounts')?.classList.contains('active'))load();
}
async function load(){const seq=++epoch;detailEpoch++;const host=$('panel-accounts');if(!host||!config)return;host.textContent='Loading accounts…';
 try{const d=await config.api('/api/crm/accounts');if(seq!==epoch)return;rows=d.accounts;page=1;
 host.innerHTML=`<div class="section-head"><div><span class="kicker">PEOPLE & ACCESS</span><h2>Accounts Overview</h2></div><button class="btn" id="accountsRefresh">Refresh</button></div><p>One profile per exact submitted email across leads, ticket holders, checkouts and Disciple records. A profile is not proof of a verified login or a sale. Shared emails are grouped; different emails are kept separate.</p><div class="metrics">${[['Profiles',d.summary.total],['Active logins',d.summary.active],['Not activated',d.summary.notActivated],['Login disabled',d.summary.disabled],['Needs review',d.summary.review]].map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="inline-actions"><label>Search accounts<input id="accountsSearch" type="search" placeholder="Name, email, username or source"></label><label>Login status<select id="accountsStatus"><option value="">All profiles</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><p id="accountsCount" aria-live="polite"></p><div id="accountsRows"></div><div class="inline-actions"><button class="btn" id="accountsPrev">Previous</button><button class="btn" id="accountsNext">Next</button></div><section id="accountDetails" aria-live="polite"></section>`;
 $('accountsRefresh').onclick=load;for(const id of ['accountsSearch','accountsStatus'])$(id).oninput=()=>{page=1;draw()};$('accountsPrev').onclick=()=>{page--;draw()};$('accountsNext').onclick=()=>{page++;draw()};draw();
 }catch(e){if(seq===epoch)host.textContent=e.message;}
}
function draw(){const search=$('accountsSearch').value.trim().toLowerCase(),status=$('accountsStatus').value;const matched=rows.filter(a=>(!status||a.status===status)&&[a.name,a.email,a.login?.username,...a.sources].some(v=>String(v||'').toLowerCase().includes(search)));const pages=Math.max(1,Math.ceil(matched.length/50));page=Math.min(Math.max(1,page),pages);
 $('accountsCount').textContent=`${matched.length} matching profiles · Page ${page} of ${pages}`;$('accountsPrev').disabled=page===1;$('accountsNext').disabled=page===pages;
 $('accountsRows').innerHTML=table(['Account / contact','Login status','Tickets held','Paid orders','Incomplete checkouts','Partnerships','Last sign-in (Eastern)','Actions'],matched.slice((page-1)*50,page*50).map(a=>`<tr><td>${esc(a.name)}<br>${esc(a.email)}${a.login?'<br>@'+esc(a.login.username):''}</td><td>${esc(labels[a.status])}</td><td>${a.counts.tickets}</td><td>${a.counts.paidOrders}</td><td>${a.counts.carts}</td><td>${a.counts.partnerships}</td><td>${esc(date(a.login?.lastLoginAt))}</td><td><button class="btn small" data-account="${esc(a.id)}">View / manage</button></td></tr>`));
 $('accountsRows').querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>detail(b.dataset.account));
}
async function detail(id){const seq=++detailEpoch,host=$('accountDetails');host.textContent='Loading profile…';try{const response=await config.api('/api/crm/accounts/'+encodeURIComponent(id));if(seq!==detailEpoch)return;const a=response.account,d=response.details;
 host.innerHTML=`<div class="section-head"><h3>${esc(a.name)}</h3><button class="btn" id="accountClose">Close profile</button></div><p>${esc(a.email)} · ${esc(labels[a.status])}</p><p class="muted">Owner view. Viewing this profile does not sign in as this person.</p><p>Sources: ${a.sources.map(esc).join(', ')}</p><div class="inline-actions">${a.login?`<button class="btn" data-access="${a.login.disabledAt?'enable':'disable'}">${a.login.disabledAt?'Restore login access':'Disable login access'}</button><button class="btn" data-access="sign-out">Sign out all sessions</button>`:''}</div><p id="accountNotice" role="status">${a.status==='not_activated'?'No login has been activated. The person must verify their email through account setup before signing in.':a.status==='review'?'Identity records need review before this profile can be treated as an active account.':''}</p>${a.login?`<p>Username: ${esc(a.login.username)} · Created: ${esc(date(a.login.createdAt))} · Active sessions: ${a.login.activeSessions}</p>`:''}
 ${d?`<h4>Tickets held (${d.tickets.length})</h4>${table(['Event','Ticket','Holder','Admission','Check-in','Ticket code'],d.tickets.map(t=>`<tr><td>${esc(t.event)}</td><td>${esc(t.name)}</td><td>${esc(t.holderName)}</td><td>${esc(t.kind)}</td><td>${t.checkedIn?'Checked in':'Not checked in'}</td><td>${esc(t.code)}</td></tr>`))}
 <h4>Items remaining in cart (${d.carts.length} incomplete checkouts)</h4><p class="muted">Unpaid attempts are not sales. Expired items require a new checkout at current availability and pricing.</p>${orderTable(d.carts)}
 <h4>Purchases & checkout history</h4>${orderTable(d.orders)}
 <h4>Partnerships & vendor spots</h4>${table(['Organization','Category','Application stage','Event','Space','Assignment'],d.partnerships.map(p=>`<tr><td>${esc(p.organization)}</td><td>${p.categories.map(esc).join(', ')}</td><td>${esc(p.status)}</td><td>${esc(p.event)}</td><td>${esc(p.space)}</td><td>${esc(p.assignmentStatus)}</td></tr>`))}
 <h4>Submission activity & lead management</h4>${table(['Received (Eastern)','Source','Category','Status','Actions'],d.activity.map(r=>`<tr><td>${esc(date(r.receivedAt))}</td><td>${esc(r.source)}</td><td>${r.categories.map(esc).join(', ')}</td><td>${esc(r.status)}</td><td><button class="btn small" data-crm-record="${esc(r.id)}">Edit lead / vendor spot</button></td></tr>`))}`:'<p>Personal records are unavailable pending identity review.</p>'}`;
 $('accountClose').onclick=()=>{detailEpoch++;host.replaceChildren()};host.querySelectorAll('[data-crm-record]').forEach(b=>b.onclick=()=>window.KVNCrm?.openRecord(b.dataset.crmRecord));
 host.querySelectorAll('[data-access]').forEach(b=>b.onclick=async()=>{const action=b.dataset.access;if(!confirm((action==='disable'?'Disable login and sign out all sessions':action==='enable'?'Restore login access':'Sign out all sessions')+' for '+a.email+'? Tickets, purchases and vendor assignments remain unchanged.'))return;host.querySelectorAll('[data-access]').forEach(x=>x.disabled=true);try{await config.api('/api/crm/accounts/'+encodeURIComponent(id)+'/access',{method:'POST',body:JSON.stringify({action,version:a.login.version})});if(seq!==detailEpoch)return;await load();if(config)await detail(id);}catch(e){if(seq===detailEpoch){$('accountNotice').textContent=e.message;host.querySelectorAll('[data-access]').forEach(x=>x.disabled=false)}}});
 host.scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){if(seq===detailEpoch)host.textContent=e.message;}}
function orderTable(orders){return table(['Order','Type / event','Items','Status','Recorded total'],orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.kind)}<br>${esc(o.event)}</td><td>${o.items.map(i=>`${esc(i.quantity)} × ${esc(i.name)} ${esc(i.size)}`).join('<br>')||'Items not captured'}</td><td>${esc(o.status)}</td><td>${money(o.amountTotal)}</td></tr>`));}
window.KVNAccounts={init,clear};
})();

(()=>{'use strict';let context,sequence=0;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((Number(v)||0)/100);const table=(headers,rows)=>`<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
function counts(event,orders){const active=orders.filter(o=>o.eventId===event.id&&['paid','complimentary'].includes(o.status)&&!o.paymentAttention);const tickets=status=>active.filter(o=>o.status===status).flatMap(o=>o.tickets||[]).filter(t=>!t.status||t.status==='active');const paid=tickets('paid'),comp=tickets('complimentary');return [paid.length,comp.length,[...paid,...comp].filter(t=>t.checkedIn).length]}
function render(data,helpers){context={data,...helpers};const host=document.getElementById('eventsTable');host.innerHTML=`<p class="muted">Paid and complimentary admissions are counted separately. Expired checkouts are not ticket sales.</p><label>Show events <select id="eventVisibility"><option value="active">Active events</option><option value="archived">Archived / deleted events</option><option value="all">All events</option></select></label><div id="eventRows"></div><section id="eventReport" aria-live="polite"></section>`;document.getElementById('eventVisibility').onchange=draw;draw();}
function draw(){const {data}=context,filter=document.getElementById('eventVisibility').value;const events=data.events.filter(e=>filter==='all'||(['archived','deleted'].includes(e.status)?filter==='archived':filter==='active'));document.getElementById('eventRows').innerHTML=table(['Event','Status','Date','Paid tickets','Comp tickets','Checked in','Actions'],events.map(e=>{const c=counts(e,data.orders);return `<tr><td><button class="crm-record-link" data-detail="${esc(e.id)}">${esc(e.title)}</button></td><td>${esc(e.status)}</td><td>${esc(e.date?new Date(e.date).toLocaleDateString('en-US',{timeZone:'America/New_York'}):'—')}</td>${c.map(n=>`<td>${n}</td>`).join('')}<td><div class="inline-actions"><button class="btn small" data-detail="${esc(e.id)}">Tickets & holders</button><button class="btn small" data-edit="${esc(e.id)}">Edit event</button><button class="btn small" data-build="${esc(e.id)}">Build</button>${data.user.role==='owner'?(['archived','deleted'].includes(e.status)?`<button class="btn small" data-life="restore" data-id="${esc(e.id)}">Restore as draft</button>`:`<button class="btn small" data-life="archive" data-id="${esc(e.id)}">Archive</button>`)+`<button class="btn small" data-life="delete" data-id="${esc(e.id)}">Delete unused</button>`:''}${['draft','pending','paused'].includes(e.status)&&data.user.role==='owner'?`<button class="btn small" data-publish="${esc(e.id)}">Publish</button>`:''}${e.status==='published'?`<a class="btn small" href="/event.html?slug=${encodeURIComponent(e.slug)}" target="_blank" rel="noopener">View</a>`:''}<button class="btn small" data-url="${esc(e.id)}">URL</button></div></td></tr>`}));const host=document.getElementById('eventRows');host.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));for(const [key,handler]of [['edit','editEvent'],['build','openBuilder'],['url','customSlug']])host.querySelectorAll('[data-'+key+']').forEach(b=>b.onclick=()=>window[handler](b.dataset[key]));host.querySelectorAll('[data-publish]').forEach(b=>b.onclick=()=>window.statusEvent(b.dataset.publish,'published'));host.querySelectorAll('[data-life]').forEach(b=>b.onclick=async()=>{const action=b.dataset.life;if(!confirm(action==='archive'?'Archive this event and stop new checkout creation? Existing tickets and history remain. Previously opened payment sessions are not cancelled.':action==='delete'?'Delete this unused event from active management? Events with recorded history cannot be deleted.':'Restore this event as a draft? It will remain unavailable for new purchases until published.'))return;b.disabled=true;try{await context.api(`/api/events/${encodeURIComponent(b.dataset.id)}/lifecycle`,{method:'POST',body:JSON.stringify({action})});await context.reload()}catch(e){alert(e.message);b.disabled=false}});}
async function detail(id){const seq=++sequence,host=document.getElementById('eventReport');host.textContent='Loading ticket breakdown…';try{const d=await context.api(`/api/events/${encodeURIComponent(id)}/ticket-report`);if(seq!==sequence||!host.isConnected)return;host.innerHTML=`<h3>${esc(d.event.title)} · Tickets & holders</h3><div class="metrics">${[['Paid tickets',d.summary.paidTickets],['Comp tickets',d.summary.compTickets],['Checked in',d.summary.checkedIn],['Unpaid checkouts',d.summary.unpaidAttempts],['Refunded orders',d.summary.refundedOrders],['Paid order total',d.summary.paidAmount==null?'Restricted':money(d.summary.paidAmount)]].map(([label,value])=>`<div class="metric"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="muted">${d.summary.invalidTickets} replaced, invalid, or refunded ticket records excluded from active admissions.</p><h4>Ticket types</h4>${table(['Type','Paid','Complimentary','Checked in'],d.types.map(t=>`<tr><td>${esc(t.name)}</td><td>${t.paid}</td><td>${t.comp}</td><td>${t.checkedIn}</td></tr>`))}<h4>Ticket holders</h4><div class="inline-actions"><label>Search holders<input id="holderSearch" placeholder="Name, email, ticket or order"></label><label>Admission<select id="holderKind"><option value="">All tickets</option><option>Paid</option><option>Complimentary</option></select></label><label>Check-in<select id="holderCheck"><option value="">All</option><option value="yes">Checked in</option><option value="no">Not checked in</option></select></label><a class="btn" href="/api/events/${encodeURIComponent(id)}/holders.csv">Export all holders</a></div><p id="holderCount"></p><div id="holderRows"></div><h4>Orders & checkout attempts</h4>${table(['Order','Buyer','Items','Status','Amount'],d.orders.map(o=>`<tr><td>${esc(o.id)}</td><td>${esc(o.buyerName)}<br>${esc(o.buyerEmail)}</td><td>${o.items.map(i=>`${esc(i.quantity)} × ${esc(i.name)}`).join('<br>')}</td><td>${esc(o.status)}</td><td>${money(o.amountTotal)}</td></tr>`))}`;const drawHolders=()=>{const search=document.getElementById('holderSearch').value.toLowerCase(),kind=document.getElementById('holderKind').value,check=document.getElementById('holderCheck').value;const rows=d.holders.filter(t=>(!kind||t.kind===kind)&&(!check||t.checkedIn===(check==='yes'))&&[t.code,t.orderId,t.holderName,t.holderEmail,t.buyerEmail].some(v=>String(v||'').toLowerCase().includes(search)));document.getElementById('holderCount').textContent=`${rows.length} matching tickets`;document.getElementById('holderRows').innerHTML=table(['Holder','Ticket','Admission','Check-in','Order'],rows.map(t=>`<tr><td>${esc(t.holderName)}<br>${esc(t.holderEmail)}</td><td>${esc(t.ticketName)}<br>${esc(t.code)}</td><td>${esc(t.kind)}</td><td>${t.checkedIn?'Checked in':'Not checked in'}</td><td>${esc(t.orderId)}</td></tr>`))};for(const id of ['holderSearch','holderKind','holderCheck'])document.getElementById(id).oninput=drawHolders;drawHolders();host.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){if(seq===sequence)host.textContent=e.message;}}
window.KVNEvents={render,clear(){sequence++;context=null;document.getElementById('eventsTable')?.replaceChildren()}};
})();

const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((c||0)/100);let data=null,analytics=null,audit=[],superData=null,shopData=null,systemHealth=null,selectedBlock=null,builderLayout=[];const $=id=>document.getElementById(id),esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function api(url,opt={}){opt.headers={...(opt.headers||{})};if(opt.body&&!opt.headers['Content-Type'])opt.headers['Content-Type']='application/json';const r=await fetch(url,opt);let d;try{d=await r.json()}catch{d={}}if(!r.ok)throw new Error(d.error||'Request failed');return d}
let dashboardEpoch=0;
async function loadDashboard(){const epoch=dashboardEpoch;try{const result=await api('/api/dashboard');if(epoch!==dashboardEpoch)return;data=result;$('dashNav').hidden=false;$('loginGate').hidden=true;$('dashboard').hidden=false;$('whoami').textContent=`${data.user.name} • ${data.user.role}`;$('roleLabel').textContent=data.user.role==='owner'?'PLATFORM OWNER':data.user.role==='staff'?'STAFF WORKSPACE':'ORGANIZER WORKSPACE';document.querySelectorAll('.owner-only').forEach(x=>x.style.display=data.user.role==='owner'?'':'none');renderAll();window.KVNBusiness?.init({api,showPanel,user:data.user});window.KVNCrm?.init({api,showPanel,user:data.user});window.KVNAccounts?.init({api,showPanel,user:data.user});window.KVNActivity?.init({api,user:data.user});window.KVNMarketing?.init({api,user:data.user});if($('panel-sms')?.classList.contains('active'))window.KVNSms?.init({api,user:data.user});window.KVNAgreements?.init({api,user:data.user});window.KVNController?.init({api,user:data.user});loadAsync()}catch(e){if(epoch!==dashboardEpoch)return;data=null;$('dashNav').hidden=true;$('whoami').textContent='Not signed in';window.KVNCrm?.clear();window.KVNAccounts?.clear();window.KVNEvents?.clear();window.KVNActivity?.clear();window.KVNBusiness?.clear();window.KVNMarketing?.clear();window.KVNSms?.clear();window.KVNAgreements?.clear();window.KVNController?.clear();$('loginGate').hidden=false;$('dashboard').hidden=true}}
async function loadAsync(){try{analytics=await api('/api/analytics');renderAnalytics()}catch{}try{audit=(await api('/api/audit')).logs;renderAudit()}catch{}if(data?.user.role==='owner'){try{systemHealth=await api('/api/system-health');renderSystemHealth()}catch(error){systemHealth={status:'attention',summary:{emailAttention:0},checks:[],recentFailures:[]};renderSystemHealth(error.message)}try{superData=await api('/api/super-admin');renderSuper()}catch{}try{await loadShop()}catch{}}}
function table(rows,heads){return `<div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${heads.length}" class="muted">No records yet.</td></tr>`}</tbody></table></div>`}
function renderAll(){if($('refundSummary'))$('refundSummary').textContent=`Refunded event orders: ${data.metrics.refundedOrderCount||0} · original order value ${money(data.metrics.refundedOrderOriginalAmount)} (not a net revenue figure). Standalone apparel is reported in Apparel / Shop.`;$('mGross').textContent=money(data.metrics.gross);$('mOrders').textContent=data.metrics.orders;$('mTickets').textContent=data.metrics.tickets;$('mEvents').textContent=data.metrics.events;renderOverview();renderEvents();renderKingdomDisciples();renderDiscipleFinancials();renderOrders();renderDiscounts();renderStaff();renderOrgs();renderPayouts();renderOnboarding();const opts=data.events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('');$('builderEvent').innerHTML=opts;$('exportEvent').innerHTML=opts;if(data.events.length)loadBuilder(data.events[0].id)}
function renderDisciples(){if(data.user.role!=='owner')return;const apps=data.discipleApplications||[],disciples=data.disciples||[];$('dPending').textContent=apps.filter(a=>['submitted','resubmitted','needs_info'].includes(a.status)).length;$('dActive').textContent=disciples.filter(d=>d.status==='active').length;$('discipleApplications').innerHTML=table(apps.map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="muted">${esc(a.applicationReference)}</div></td><td>${esc(a.market||[a.city,a.state].filter(Boolean).join(', '))}</td><td><span class="status ${a.status}">${esc(a.status)}</span></td><td>${new Date(a.submittedAt).toLocaleDateString()}</td><td><div class="inline-actions">${['submitted','resubmitted','needs_info'].includes(a.status)?`<button class="btn small primary" onclick="discipleStatus('${a.id}','approved')">Approve</button><button class="btn small" onclick="discipleStatus('${a.id}','needs_info')">Need Info</button><button class="btn small danger" onclick="discipleStatus('${a.id}','rejected')">Reject</button>`:''}</div></td></tr>`),['Applicant','Market','Status','Submitted','Action']);$('disciplesTable').innerHTML=table(disciples.map(d=>`<tr><td><button class="profile-link" onclick="viewDisciple('${d.id}')"><strong>${esc(d.name)}</strong></button><div class="muted">${esc(d.email)}</div></td><td><a target="_blank" href="${discipleLink(d)}">${esc(discipleLink(d))}</a></td><td><span class="status ${d.status}">${esc(d.status)}</span></td><td>${esc(d.welcomeEmail?.status||'—')}</td></tr>`),['Disciple','Personal Link','Status','Welcome Email'])}
window.discipleStatus=async(id,status)=>{const action=status==='approved'?'approve':status==='rejected'?'reject':'request more information from';let reason='';if(status!=='approved'){reason=prompt(status==='needs_info'?'What information or action is required?':'Reason for rejection:')||'';if(!reason.trim())return}if(!confirm('Are you sure you want to '+action+' this Disciple application?'))return;try{const result=await api('/api/disciple-applications/'+encodeURIComponent(id)+'/status',{method:'POST',body:JSON.stringify({status,reason})});discipleNotice(status==='approved'&&result.trackingUrl?`Disciple approved. Personal link: ${result.trackingUrl}`:`Application updated to ${status}; applicant notice ${result.notification?.status||'recorded'}.`);await loadDashboard()}catch(error){discipleNotice(error.message,'error')}};
function renderOverview(){$('overviewEvents').innerHTML=data.events.slice(0,6).map(e=>`<div class="event-card"><div><span class="status ${e.status}">${e.status}</span><h3>${esc(e.title)}</h3><div class="event-meta">${esc(e.location)} • /${esc(e.slug)}</div></div><div class="inline-actions"><button class="btn small" onclick="openBuilder('${e.id}')">Build</button>${data.user.role==='owner'&&e.status==='pending'?`<button class="btn small primary" onclick="statusEvent('${e.id}','published')">Approve</button>`:''}</div></div>`).join('')||'<div class="card">No events yet.</div>'}
function renderEvents(){window.KVNEvents.render(data,{api,reload:loadDashboard})}
function renderOrders(){
 $('ordersTable').innerHTML=table(data.orders.map(o=>`<tr><td><strong>${esc(o.id)}</strong><div class="muted">${new Date(o.createdAt).toLocaleString()}</div></td><td>${esc(o.buyerName||'')}<div class="muted">${esc(o.buyerEmail||'')}</div></td><td>${esc(o.status)}</td><td>${o.tickets?.length||0}</td><td>${money(o.amountTotal)}</td><td>Pass email: ${esc(o.bundleFulfillment?.pass||'pending')}<br>Tee: ${esc(o.bundleFulfillment?.tee||'not_required')}<br>${esc(o.bundleShipment?.carrier||'')} ${esc(o.bundleShipment?.trackingNumber||'')}<br>Staff notice: ${esc(o.fulfillmentEmail?.status||'pending')}<br>Shipping email: ${esc(o.shipmentEmail?.status||'pending')}</td><td><div class="inline-actions">${o.status==='paid'?`<button class="btn small" onclick="resend('${o.id}')">Resend pass</button>${['awaiting_shipment','shipped'].includes(o.bundleFulfillment?.tee)?`<button class="btn small" onclick="bundleShip('${o.id}')">${o.bundleShipment?'Retry shipping email':'Ship tee'}</button><button class="btn small" onclick="bundleNotice('${o.id}')">Staff notice</button>`:''}<button class="btn small" onclick="transferFromOrder('${o.id}')">Transfer</button><button class="btn small danger" onclick="refund('${o.id}')">Refund</button>`:''}</div></td></tr>`),['Order','Buyer','Status','Tickets','Total','Fulfillment','Actions']);
}
window.bundleShip=async id=>{const order=data.orders.find(o=>o.id===id);const carrier=order.bundleShipment?.carrier||prompt('Shipping carrier:');if(!carrier)return;const trackingNumber=order.bundleShipment?.trackingNumber||prompt('Tracking number:');if(!trackingNumber)return;try{const result=await api(`/api/orders/${id}/ship`,{method:'POST',body:JSON.stringify({carrier,trackingNumber})});alert(result.shipmentEmail?.status==='sent'?'Shipment saved; shipping email accepted.':'Shipment saved. Email needs attention: '+(result.shipmentEmail?.error||'not sent'));await loadDashboard();}catch(error){alert(error.message);}};
window.bundleNotice=async id=>{try{const result=await api(`/api/orders/${id}/fulfillment-notice`,{method:'POST',body:'{}'});alert(result.fulfillmentEmail?.status==='sent'?'Staff notice accepted.':result.fulfillmentEmail?.error||'No apparel to fulfill.');await loadDashboard();}catch(error){alert(error.message);}};

async function loadShop(){const status=$('shopStatus')?.value||'';shopData=await api('/api/shop/orders'+(status?'?status='+encodeURIComponent(status):''));renderShop()}
function renderShop(){if(!shopData)return;const m=shopData.metrics||{};$('sGross').textContent=money(m.grossRevenue);$('sOrders').textContent=m.paidOrders||0;$('sUnits').textContent=m.unitsSold||0;$('sRemaining').textContent=m.unitsRemaining||0;const inventory=(shopData.products||[]).flatMap(product=>Object.entries(product.sizeInventory||{}).map(([size,count])=>`<div class="metric"><span>${esc(size)}</span><strong>${Number(count)}</strong></div>`));$('shopInventory').innerHTML=inventory.join('')||'<div class="card muted">No inventory configured.</div>';$('shopOrders').innerHTML=table((shopData.orders||[]).map(order=>{const items=(order.items||[]).map((item,index)=>`${esc(item.size)} × ${Number(item.quantity)} <button class="btn small" onclick="shopSize('${order.id}',${index})">Change</button>`).join('<br>');const numbers=(order.collectorNumbers||[]).join(', ')||'Pending';return `<tr><td><strong>${esc(order.id)}</strong><div class="muted">${new Date(order.createdAt).toLocaleString()}</div></td><td>${esc(order.buyerName||'')}<div class="muted">${esc(order.buyerEmail||'')}</div></td><td>${items}</td><td>${esc(numbers)}</td><td><span class="status ${esc(order.fulfillmentStatus||order.status)}">${esc(order.fulfillmentStatus||order.status)}</span>${order.trackingNumber?`<div class="muted">${esc(order.carrier)} ${esc(order.trackingNumber)}</div>`:''}</td><td>${money(order.amountTotal)}</td><td><div class="inline-actions"><button class="btn small" onclick="shopResend('${order.id}')">Resend</button>${order.status==='paid'&&order.fulfillmentStatus!=='shipped'?`<button class="btn small primary" onclick="shopShip('${order.id}')">Ship</button>`:''}${order.status==='paid'?`<button class="btn small danger" onclick="shopRefund('${order.id}')">Refund</button>`:''}</div></td></tr>`}),['Order','Buyer','Items','Collector #','Fulfillment','Total','Actions'])}
window.shopResend=async id=>{await api(`/api/shop/orders/${id}/resend`,{method:'POST',body:'{}'});alert('Shop confirmation resent.')};
window.shopShip=async id=>{const carrier=prompt('Shipping carrier (for example UPS):');if(!carrier)return;const trackingNumber=prompt('Tracking number:');if(!trackingNumber)return;await api(`/api/shop/orders/${id}/ship`,{method:'POST',body:JSON.stringify({carrier,trackingNumber})});await loadShop()};
window.shopSize=async(id,itemIndex)=>{const size=prompt('New size: S, M, L, XL, 2XL, 3XL, or 4XL');if(!size)return;await api(`/api/shop/orders/${id}/size`,{method:'PATCH',body:JSON.stringify({itemIndex,size:size.toUpperCase()})});await loadShop()};
window.shopRefund=async id=>{if(!confirm('Refund this apparel order? Inventory will be restored, but Collector numbers will not be reused.'))return;await api(`/api/shop/orders/${id}/refund`,{method:'POST',body:'{}'});await loadShop()};
function renderDiscounts(){$('discountTable').innerHTML=table(data.discounts.map(d=>`<tr><td><strong>${esc(d.code)}</strong></td><td>${d.type==='percent'?`${d.value}%`:money(d.value)}</td><td>${d.uses} / ${d.maxUses}</td><td>${d.active?'Active':'Off'}</td></tr>`),['Code','Value','Uses','Status'])}
function renderStaff(){$('staffTable').innerHTML=table((data.staff||[]).map(u=>`<tr><td><strong>${esc(u.name)}</strong><div class="muted">${esc(u.email)}</div></td><td>${(u.permissions||[]).map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')}</td><td><button class="btn small danger" onclick="removeStaff('${u.id}')">Remove</button></td></tr>`),['Staff','Permissions','Action'])}
function renderOrgs(){if(data.user.role!=='owner')return;$('orgTable').innerHTML=table(data.organizations.map(o=>`<tr><td><strong>${esc(o.name)}</strong><div class="muted">/${esc(o.slug)}</div></td><td><span class="status ${o.status}">${o.status}</span></td><td>${esc(o.feePlanId||'standard')}</td><td>${esc(o.payoutSchedule||'weekly')}</td><td>${o.status==='pending'?`<button class="btn small primary" onclick="approveOrg('${o.id}')">Approve</button>`:''}</td></tr>`),['Organization','Status','Fee Plan','Payouts','Action'])}
function renderPayouts(){const org=data.organizations[0];$('payoutControls').innerHTML=org?`<div class="card form-row"><label>Payout schedule<select id="payoutSchedule"><option>daily</option><option>weekly</option><option>monthly</option><option>manual</option></select></label><button class="btn" onclick="savePayoutSchedule('${org.id}')">Save Schedule</button>${data.user.role==='owner'?`<label>Fee plan<select id="feePlan">${(data.settings.feePlans||[]).map(p=>`<option value="${p.id}">${p.name} — ${p.percent}%</option>`).join('')}</select></label><button class="btn" onclick="saveFeePlan('${org.id}')">Apply Fee Plan</button>`:''}</div>`:'';$('payoutTable').innerHTML=table((data.payouts||[]).map(p=>`<tr><td>${p.id}</td><td>${money(p.amount)}</td><td>${p.status}</td><td>${new Date(p.scheduledFor).toLocaleString()}</td></tr>`),['Payout','Amount','Status','Scheduled'])}
function renderOnboarding(){const org=data.organizations[0];const steps=org?.onboarding||{};$('onboardingWizard').innerHTML=`<div class="onboarding-grid">${[['profile','Organization Profile'],['branding','Branding & Logo'],['payouts','Stripe Payouts'],['firstEvent','Publish First Event']].map(([k,t])=>`<button class="onboard-step ${steps[k]?'done':''}" onclick="toggleOnboarding('${org?.id}','${k}',${!steps[k]})"><strong>${steps[k]?'✓':'○'} ${t}</strong><span>${steps[k]?'Complete':'Needs attention'}</span></button>`).join('')}</div>`}
function renderAnalytics(){if(!analytics)return;$('aCarts').textContent=analytics.abandoned.length;const denom=analytics.conversion.orders+analytics.conversion.carts;$('aConv').textContent=denom?Math.round(analytics.conversion.orders/denom*100)+'%':'—';const max=Math.max(1,...analytics.salesByDay.map(x=>x.total));$('salesChart').innerHTML=analytics.salesByDay.length?analytics.salesByDay.map(x=>`<div class="bar-col" title="${x.date}: ${money(x.total)}"><div class="bar" style="height:${Math.max(6,x.total/max*150)}px"></div><small>${x.date.slice(5)}</small></div>`).join(''):'<p class="muted">Sales will appear here after paid orders.</p>';$('abandonedTable').innerHTML=table(analytics.abandoned.map(c=>`<tr><td>${esc(c.email||'Anonymous')}</td><td>${money(c.amount)}</td><td>${(c.items||[]).length}</td><td>${new Date(c.updatedAt).toLocaleString()}</td><td>${esc(c.recoveryEmail?.status||'Not sent')}${c.recoveryEmail?.attemptedAt?'<br>'+new Date(c.recoveryEmail.attemptedAt).toLocaleString():''}${c.recoveryEmail?.error?'<br>'+esc(c.recoveryEmail.error):''}</td><td>${data?.user.role==='owner'&&c.email&&!c.recoveryEmail?`<button class="btn small" data-recovery-cart="${esc(c.id)}">Send Recovery Email</button>`:''}</td></tr>`),['Lead','Cart Value','Items','Last Activity','Recovery Email','Action']);$('abandonedTable').querySelectorAll('[data-recovery-cart]').forEach(button=>button.onclick=()=>window.KVNMarketing?.recovery(button.dataset.recoveryCart))}
function renderAudit(){$('auditTable').innerHTML=table(audit.map(l=>`<tr><td>${new Date(l.createdAt).toLocaleString()}</td><td>${esc(l.userName)}</td><td>${esc(l.action)}</td><td>${esc(l.entityType)} • ${esc(l.entityId)}</td></tr>`),['Time','User','Action','Target'])}
function renderSuper(){if(!superData)return;const m=superData.metrics;$('superMetrics').innerHTML=`<div class="metric"><span>Platform GMV</span><strong>${money(m.grossVolume)}</strong></div><div class="metric"><span>Paid orders</span><strong>${m.paidOrders}</strong></div><div class="metric"><span>Organizers</span><strong>${m.organizers}</strong></div><div class="metric"><span>Open carts</span><strong>${m.openCarts}</strong></div>`}
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('open');bindModalForms()}window.closeModal=()=>$('modal').classList.remove('open');
function bindModalForms(){const f=$('eventForm');if(f)f.onsubmit=saveEvent;const p=$('productForm');if(p)p.onsubmit=saveConfiguredProduct;const d=$('discountForm');if(d)d.onsubmit=saveDiscount;const s=$('staffForm');if(s)s.onsubmit=saveStaff;const disciple=$('discipleEditForm');if(disciple)disciple.onsubmit=saveDisciple;const credit=$('discipleCreditForm');if(credit)credit.onsubmit=saveDiscipleCredit}
window.openNewEvent=()=>openModal('Create Event',eventFormHtml({}));$('newEvent').onclick=openNewEvent;
function eventFormHtml(e){return `<form id="eventForm" class="form-stack"><input type="hidden" name="id" value="${e.id||''}"><label>Title<input name="title" required value="${esc(e.title||'')}"></label><label>Subtitle<input name="subtitle" value="${esc(e.subtitle||'')}"></label><label>Description<textarea name="description">${esc(e.description||'')}</textarea></label><div class="two-col"><label>Date & time<input type="datetime-local" name="date" value="${e.date?e.date.slice(0,16):''}"></label><label>Venue<input name="venue" value="${esc(e.venue||'')}"></label></div><label>Location<input name="location" value="${esc(e.location||'')}"></label><label>Tax rate %<input type="number" step="0.01" name="taxRatePercent" value="${e.taxRatePercent||0}"></label><button class="btn primary">Save Event</button></form>`}
window.editEvent=id=>{const e=data.events.find(x=>x.id===id);openModal('Edit Event',eventFormHtml(e))};async function saveEvent(ev){ev.preventDefault();const fd=new FormData(ev.target),obj=Object.fromEntries(fd);const id=obj.id;delete obj.id;const tax=obj.taxRatePercent;delete obj.taxRatePercent;let r;if(id){r=await api(`/api/events/${id}`,{method:'PUT',body:JSON.stringify(obj)});await api(`/api/events/${id}/tax`,{method:'POST',body:JSON.stringify({rate:tax})})}else r=await api('/api/events',{method:'POST',body:JSON.stringify(obj)});closeModal();await loadDashboard()}
window.statusEvent=async(id,status)=>{await api(`/api/events/${id}/status`,{method:'POST',body:JSON.stringify({status})});loadDashboard()};window.approveOrg=async id=>{await api(`/api/organizations/${id}/approve`,{method:'POST',body:'{}'});loadDashboard()};
window.customSlug=id=>{const e=data.events.find(x=>x.id===id);openModal('Custom Event URL',`<div class="form-stack"><label>kingdomvibetickets.com/event/<input id="slugInput" value="${esc(e.slug)}"></label><button class="btn primary" id="saveSlug">Save URL</button></div>`);$('saveSlug').onclick=async()=>{await api(`/api/events/${id}/custom-slug`,{method:'POST',body:JSON.stringify({slug:$('slugInput').value})});closeModal();loadDashboard()}}
function loadBuilder(id){const e=data.events.find(x=>x.id===id);if(!e)return;builderLayout=JSON.parse(JSON.stringify(e.layout||[]));selectedBlock=null;renderBuilder()}window.openBuilder=id=>{$('builderEvent').value=id;showPanel('builder');loadBuilder(id)};$('builderEvent').onchange=e=>loadBuilder(e.target.value);
function renderBuilder(){$('builderCanvas').innerHTML=builderLayout.length?builderLayout.map((b,i)=>`<div class="canvas-block ${selectedBlock===b.id?'selected':''}" draggable="true" data-index="${i}" data-id="${b.id}"><span class="badge">${b.type}</span><h3>${esc(b.title||'Untitled')}</h3><p>${esc(b.body||'')}</p></div>`).join(''):'<div class="empty-drop">Drag blocks here</div>';document.querySelectorAll('.canvas-block').forEach(el=>{el.onclick=()=>{selectedBlock=el.dataset.id;renderBuilder();renderBlockSettings()};el.ondragstart=e=>{e.dataTransfer.setData('text/index',el.dataset.index);el.classList.add('dragging')};el.ondragend=()=>el.classList.remove('dragging')});renderBlockSettings();renderBuilderProducts()}
function renderBlockSettings(){const b=builderLayout.find(x=>x.id===selectedBlock);$('blockSettings').innerHTML=b?`<div class="form-stack"><label>Heading<input id="blockTitle" value="${esc(b.title||'')}"></label><label>Body<textarea id="blockBody">${esc(b.body||'')}</textarea></label><label>Width<select id="blockWidth"><option value="full">Full</option><option value="wide">Wide</option><option value="half">Half</option></select></label><button class="btn" id="applyBlock">Apply</button><button class="btn danger" id="deleteBlock">Delete</button></div>`:'<p class="muted">Nothing selected.</p>';if(b){$('blockWidth').value=b.width||'full';$('applyBlock').onclick=()=>{b.title=$('blockTitle').value;b.body=$('blockBody').value;b.width=$('blockWidth').value;renderBuilder()};$('deleteBlock').onclick=()=>{builderLayout=builderLayout.filter(x=>x.id!==b.id);selectedBlock=null;renderBuilder()}}}
$('builderCanvas').ondragover=e=>e.preventDefault();$('builderCanvas').ondrop=e=>{e.preventDefault();const ni=e.dataTransfer.getData('text/newtype');const from=e.dataTransfer.getData('text/index');if(ni){builderLayout.push({id:'b_'+Math.random().toString(36).slice(2,9),type:ni,title:ni==='tickets'?'Tickets':ni==='apparel'?'Apparel':ni==='hero'?'Event Hero':'New Section',body:'Click to edit this section.'});renderBuilder();return}if(from!==''){const a=Number(from),target=e.target.closest('.canvas-block');const b=target?Number(target.dataset.index):builderLayout.length-1;const [m]=builderLayout.splice(a,1);builderLayout.splice(b,0,m);renderBuilder()}};document.querySelectorAll('.tool').forEach(t=>{t.ondragstart=e=>e.dataTransfer.setData('text/newtype',t.dataset.newtype);t.onclick=()=>{builderLayout.push({id:'b_'+Math.random().toString(36).slice(2,9),type:t.dataset.newtype,title:'New '+t.textContent,body:'Click to edit.'});renderBuilder()}});$('saveBuilder').onclick=async()=>{await api(`/api/events/${$('builderEvent').value}`,{method:'PUT',body:JSON.stringify({layout:builderLayout})});alert('Page saved.');loadDashboard()};
$('uploadHero').onclick=()=>$('heroFile').click();$('heroFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;const dataUrl=await new Promise(r=>{const rd=new FileReader();rd.onload=()=>r(rd.result);rd.readAsDataURL(f)});await api(`/api/events/${$('builderEvent').value}/media`,{method:'POST',body:JSON.stringify({kind:'hero',dataUrl})});alert('Hero image uploaded.');loadDashboard()};
$('addProduct').onclick=()=>openModal('Add Ticket or Apparel',`<form id="productForm" class="form-stack"><input type="hidden" name="eventId" value="${$('builderEvent').value}"><label>Type<select name="type"><option value="ticket">Ticket</option><option value="apparel">Apparel</option></select></label><label>Name<input name="name" required></label><label>Description<textarea name="description"></textarea></label><div class="two-col"><label>Price ($)<input type="number" step="0.01" name="price" required></label><label>Inventory<input type="number" name="inventory" required></label></div><label>Apparel sizes<input name="sizes" value="S,M,L,XL,2XL,3XL"></label><button class="btn primary">Add Product</button></form>`);async function saveProduct(e){e.preventDefault();const fd=new FormData(e.target),x=Object.fromEntries(fd);await api(`/api/events/${x.eventId}/products`,{method:'POST',body:JSON.stringify({type:x.type,name:x.name,description:x.description,price:Math.round(Number(x.price)*100),inventory:Number(x.inventory),options:x.type==='apparel'?{size:x.sizes.split(',').map(s=>s.trim()).filter(Boolean)}:undefined})});closeModal();loadDashboard()};$('editEventInfo').onclick=()=>editEvent($('builderEvent').value);
$('newDiscount').onclick=()=>openModal('New Discount',`<form id="discountForm" class="form-stack"><label>Event<select name="eventId">${data.events.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></label><label>Code<input name="code" required></label><label>Type<select name="type"><option value="percent">Percent</option><option value="fixed">Fixed Dollars</option></select></label><label>Value<input name="value" type="number" step="0.01" required></label><label>Maximum uses<input name="maxUses" type="number" value="100"></label><button class="btn primary">Create</button></form>`);async function saveDiscount(e){e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(x.type==='fixed')x.value=Math.round(Number(x.value)*100);await api('/api/discounts',{method:'POST',body:JSON.stringify(x)});closeModal();loadDashboard()}
$('newStaff').onclick=()=>openModal('Add Staff',`<form id="staffForm" class="form-stack"><label>Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Permissions<select name="permissions" multiple size="5"><option value="checkin">Check-In</option><option value="attendees">Attendees</option><option value="orders">Orders</option><option value="events">Events</option><option value="refunds">Refunds</option></select></label><button class="btn primary">Add Staff</button></form>`);async function saveStaff(e){e.preventDefault();const fd=new FormData(e.target);await api('/api/staff',{method:'POST',body:JSON.stringify({name:fd.get('name'),email:fd.get('email'),permissions:fd.getAll('permissions')})});closeModal();loadDashboard()}window.removeStaff=async id=>{await api(`/api/staff/${id}`,{method:'DELETE'});loadDashboard()};
$('exportCsv').onclick=()=>{const id=$('exportEvent').value;location.href=`/api/events/${id}/attendees.csv`};window.resend=async id=>{await api(`/api/orders/${id}/resend`,{method:'POST',body:'{}'});alert('Confirmation resent.')};window.transferFromOrder=id=>{const o=data.orders.find(x=>x.id===id),t=o?.tickets?.[0];if(!t)return;openModal('Transfer Ticket',`<div class="form-stack"><p>${esc(t.code)} • ${esc(t.ticketName)}</p><label>New holder<input id="transferName" value="${esc(t.holderName||'')}"></label><label>New email<input id="transferEmail" type="email"></label><button class="btn primary" id="doTransfer">Transfer</button></div>`);$('doTransfer').onclick=async()=>{await api(`/api/tickets/${t.code}/transfer`,{method:'POST',body:JSON.stringify({name:$('transferName').value,email:$('transferEmail').value})});closeModal();loadDashboard()}};window.refund=async id=>{if(confirm('Refund this order?')){await api(`/api/orders/${id}/refund`,{method:'POST',body:'{}'});loadDashboard()}};
$('shopStatus').onchange=()=>loadShop();
window.savePayoutSchedule=async org=>{await api(`/api/organizations/${org}/payout-schedule`,{method:'POST',body:JSON.stringify({schedule:$('payoutSchedule').value})});loadDashboard()};window.saveFeePlan=async org=>{await api(`/api/organizations/${org}/fee-plan`,{method:'POST',body:JSON.stringify({feePlanId:$('feePlan').value})});loadDashboard()};window.toggleOnboarding=async(org,key,value)=>{await api(`/api/organizations/${org}/onboarding`,{method:'POST',body:JSON.stringify({onboarding:{[key]:value}})});loadDashboard()};

function discipleNotice(message,type='success'){const target=$('discipleNotice');if(!target)return;target.hidden=false;target.className=`operation-notice ${type}`;target.textContent=message}
function discipleLink(d){const base=String('https://kvnlive.com/affiliate').replace(/\/$/,'');return `${base}/${encodeURIComponent(d.handle||'')}`}
function renderSystemHealth(error=''){if(!$('discipleHealth'))return;const health=systemHealth||{checks:[],summary:{emailAttention:0}};$('dEmailAttention').textContent=health.summary?.emailAttention||0;$('discipleHealth').innerHTML=error?`<div class="health-card failed"><strong>Health check unavailable</strong><span>${esc(error)}</span></div>`:(health.checks||[]).map(item=>`<div class="health-card ${esc(item.status)}"><div><span class="health-dot"></span><strong>${esc(item.label)}</strong></div><span>${esc(item.detail)}</span></div>`).join('')||'<div class="card muted">No health checks returned.</div>'}
function kingdomDiscipleActions(d){const leader=d.isKingdomLeader,active=d.status==='active';return `<div class="action-grid"><a class="btn small" href="https://kvnlive.com/member?preview=${encodeURIComponent(d.id)}">View as Disciple</a><button class="btn small" onclick="copyDiscipleLink('${d.id}')">Copy Link</button><button class="btn small" onclick="testDiscipleLink('${d.id}')">Test Link</button><button class="btn small" onclick="resendWelcome('${d.id}')">Resend Welcome</button><button class="btn small" onclick="editDisciple('${d.id}')">Edit</button><button class="btn small ${active?'danger':''}" onclick="toggleDiscipleActive('${d.id}',${!active})">${active?'Deactivate':'Reactivate'}</button><button class="btn small" onclick="toggleKingdomLeader('${d.id}',${!leader})">${leader?'Remove':'Make'} Kingdom Leader</button><button class="btn small" onclick="assignKingdomTeam('${d.id}')">Assign Team</button>${leader?`<button class="btn small" onclick="triggerLeaderBundle('${d.id}')">Complimentary Bundle</button>`:`<button class="btn small" onclick="inviteDiscipleBundle('${d.id}')">Optional Bundle</button>`}<button class="btn small" onclick="creditDiscipleSale('${d.id}')">Credit Sale</button></div>`}
function discipleStats(d){const commissions=(data.discipleCommissions||[]).filter(x=>x.discipleId===d.id&&x.status!=='reversed'),orders=(data.orders||[]).filter(o=>o.discipleId===d.id||String(o.discipleCode||'').toUpperCase()===String(d.code||'').toUpperCase()),eligible=commissions.reduce((n,x)=>n+Number(x.eligibleBase||0),0),earned=commissions.reduce((n,x)=>n+Number(x.amount||0),0),paid=commissions.filter(x=>x.status==='paid').reduce((n,x)=>n+Number(x.amount||0),0);return {orders:orders.length,eligible,earned,paid,pending:earned-paid}}
window.viewDisciple=id=>{const d=(data.disciples||[]).find(x=>x.id===id);if(!d)return;const s=discipleStats(d),teams=data.discipleTeams||[],teamCount=teams.filter(t=>t.leaderId===d.id&&!t.endedAt).length,attempts=(d.welcomeEmailAttempts||[]).slice().reverse(),link=discipleLink(d);openModal('Kingdom Disciple Profile',`<div class="form-stack"><div><span class="kicker">DISCIPLE PROFILE</span><h2 style="margin-bottom:4px">${esc(d.name)}</h2><div class="muted">${esc(d.email)}</div></div><div class="metrics"><div class="metric"><span>Attributed sales</span><strong>${money(s.eligible)}</strong></div><div class="metric"><span>Conversions</span><strong>${s.orders}</strong></div><div class="metric"><span>Commission earned</span><strong>${money(s.earned)}</strong></div><div class="metric"><span>Pending</span><strong>${money(s.pending)}</strong></div></div><div class="card"><strong>Personal Disciple Link</strong><p><a target="_blank" href="${link}">${esc(link)}</a></p><div class="inline-actions"><button class="btn primary" onclick="copyDiscipleLink('${d.id}')">Copy Link</button><button class="btn" onclick="testDiscipleLink('${d.id}')">Open Link</button><button class="btn" onclick="resendWelcome('${d.id}')">Resend Welcome</button></div></div><div class="card"><h3>Program Details</h3><p><strong>Status:</strong> ${esc(d.status||'—')} &nbsp; <strong>Role:</strong> ${d.isKingdomLeader?'Kingdom Leader':'Kingdom Disciple'} &nbsp; <strong>Commission:</strong> ${Number(d.defaultCommissionPercent||10)}%</p><p><strong>Direct team:</strong> ${teamCount} &nbsp; <strong>Paid commissions:</strong> ${money(s.paid)}</p></div><div class="card"><h3>Welcome Email</h3><p><strong>Latest:</strong> ${esc(d.welcomeEmail?.status||'Not sent')}${d.welcomeEmail?.sentAt?` • ${new Date(d.welcomeEmail.sentAt).toLocaleString()}`:''}</p>${d.welcomeEmail?.error?`<p class="attention-text">${esc(d.welcomeEmail.error)}</p>`:''}${attempts.length?`<div class="muted">${attempts.slice(0,5).map(a=>`${esc(a.status)} • ${a.sentAt||a.failedAt||a.attemptedAt?new Date(a.sentAt||a.failedAt||a.attemptedAt).toLocaleString():'—'}`).join('<br>')}</div>`:''}</div><div class="card"><h3>Management</h3>${kingdomDiscipleActions(d)}</div></div>`)}
window.copyDiscipleLink=async id=>{const disciple=(data.disciples||[]).find(item=>item.id===id);if(!disciple)return;const link=discipleLink(disciple);try{await navigator.clipboard.writeText(link);discipleNotice(`Copied ${link}`)}catch{prompt('Copy this personal link:',link)}};
window.testDiscipleLink=id=>{const disciple=(data.disciples||[]).find(item=>item.id===id);if(disciple)window.open(discipleLink(disciple),'_blank','noopener')};
window.resendWelcome=async id=>{if(!confirm('Resend this Disciple welcome email now?'))return;discipleNotice('Sending welcome email…');try{const result=await api(`/api/disciples/${id}/welcome/resend`,{method:'POST',body:'{}'});discipleNotice(result.welcomeEmail?.status==='sent'?('Welcome email sent'+(result.welcomeEmail?.messageId?` • ${result.welcomeEmail.messageId}`:'')+'.'):'Welcome email still needs attention.',result.welcomeEmail?.status==='sent'?'success':'error');await loadDashboard()}catch(error){discipleNotice(`Welcome email failed: ${error.message}`,'error');await loadDashboard()}};
window.toggleDiscipleActive=async(id,active)=>{if(!confirm(`${active?'Reactivate':'Deactivate'} this Disciple and personal link?`))return;try{await api(`/api/disciples/${id}/status`,{method:'POST',body:JSON.stringify({active,reason:'Owner dashboard action'})});discipleNotice(`Disciple ${active?'reactivated':'deactivated'}.`);await loadDashboard()}catch(error){discipleNotice(error.message,'error')}};
window.editDisciple=id=>{const d=(data.disciples||[]).find(item=>item.id===id);if(!d)return;openModal('Edit Kingdom Disciple',`<form id="discipleEditForm" class="form-stack"><input type="hidden" name="id" value="${esc(d.id)}"><label>Name<input name="name" required value="${esc(d.name)}"></label><label>Email<input name="email" type="email" required value="${esc(d.email)}"></label><label>Affiliate handle<input name="handle" required pattern="[a-z0-9]{1,40}" maxlength="40" value="${esc(d.handle||'')}"></label><small>Letters and numbers only. Previous links remain valid. Saving does not send an email.</small><label>Default commission %<input name="defaultCommissionPercent" type="number" min="0" max="100" step="0.01" value="${Number(d.defaultCommissionPercent||10)}"></label><label>Payout notes<textarea name="payoutNotes">${esc(d.payoutNotes||'')}</textarea></label><button class="btn primary">Save Disciple</button></form>`)};
async function saveDisciple(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));try{await api(`/api/disciples/${values.id}`,{method:'PUT',body:JSON.stringify({name:values.name,email:values.email,handle:values.handle,defaultCommissionPercent:Number(values.defaultCommissionPercent),payoutNotes:values.payoutNotes})});closeModal();discipleNotice('Disciple profile updated.');await loadDashboard()}catch(error){discipleNotice(error.message,'error')}}
window.creditDiscipleSale=id=>{const d=(data.disciples||[]).find(item=>item.id===id);if(!d)return;openModal('Credit Approved Sale',`<form id="discipleCreditForm" class="form-stack"><input type="hidden" name="id" value="${esc(d.id)}"><p class="muted">Record an eligible Kingdom Market or approved external sale for ${esc(d.name)}.</p><label>Eligible sale amount ($)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Reference<input name="reference" required></label><label>Source label<input name="sourceLabel" value="Kingdom Market" required></label><button class="btn primary">Credit Sale</button></form>`)};
async function saveDiscipleCredit(event){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));try{await api(`/api/disciples/${values.id}/credit-sale`,{method:'POST',body:JSON.stringify({amountPaid:Math.round(Number(values.amount)*100),reference:values.reference,sourceType:'kingdom_market',sourceLabel:values.sourceLabel})});closeModal();discipleNotice('Approved sale credited at the configured commission rate.');await loadDashboard()}catch(error){discipleNotice(error.message,'error')}}
window.payDiscipleCommission=async id=>{const commission=(data.discipleCommissions||[]).find(c=>c.id===id);const recipient=(data.disciples||[]).find(d=>d.id===commission?.discipleId)?.earningsRecipient;const paymentReference=prompt((recipient?'Record only after paying '+recipient+'.\n':'')+'Payment reference (ACH, check, or provider reference):');if(!paymentReference)return;try{await api(`/api/disciple-commissions/${id}/mark-paid`,{method:'POST',body:JSON.stringify({paymentReference})});discipleNotice('Commission recorded paid.');await loadDashboard()}catch(error){discipleNotice(error.message,'error')}};
window.reverseDiscipleCommissionAction=async id=>{const reason=prompt('Reversal reason:');if(!reason)return;if(!confirm('Reverse this commission?'))return;try{await api(`/api/disciple-commissions/${id}/reverse`,{method:'POST',body:JSON.stringify({reason})});discipleNotice('Commission reversed.');await loadDashboard()}catch(error){discipleNotice(error.message,'error')}};
window.toggleKingdomLeader=async(id,active)=>{const reason=prompt(`Reason to ${active?'activate':'deactivate'} Kingdom Leader:`);if(!reason)return;await api(`/api/disciples/${id}/leader-status`,{method:'POST',body:JSON.stringify({active,reason})});loadDashboard()};
window.assignKingdomTeam=async(memberId)=>{const leaderId=prompt('Kingdom Leader Disciple ID:');const reason=prompt('Assignment reason:');if(!leaderId||!reason)return;await api('/api/disciple-teams/assign',{method:'POST',body:JSON.stringify({leaderId,memberId,source:'manual',reason})});loadDashboard()};
window.triggerLeaderBundle=async id=>{if(!confirm('Create one complimentary Kingdom Leader bundle?'))return;await api(`/api/disciples/${id}/bundles/complimentary`,{method:'POST',body:JSON.stringify({campaignId:'kingdom-disciple-launch',reason:'Leader welcome bundle'})});loadDashboard()};
window.inviteDiscipleBundle=async id=>{const checkoutUrl=prompt('Secure optional bundle checkout URL:');if(!checkoutUrl)return;await api(`/api/disciples/${id}/bundles/invite`,{method:'POST',body:JSON.stringify({campaignId:'kingdom-disciple-launch',checkoutUrl})});loadDashboard()};
function renderKingdomDisciples(){if(data.user.role!=='owner')return;const allApps=data.discipleApplications||[],disciples=data.disciples||[],teams=data.discipleTeams||[],bonuses=data.discipleCommunityBonuses||[],status=$('discipleAppFilter')?.value||'',query=String($('discipleSearch')?.value||'').trim().toLowerCase(),apps=allApps.filter(a=>(!status||a.status===status)&&(!query||[a.name,a.legalFirstName,a.legalLastName,a.email,a.applicationReference].some(value=>String(value||'').toLowerCase().includes(query))));$('dPending').textContent=allApps.filter(a=>['submitted','resubmitted','needs_info'].includes(a.status)).length;$('dActive').textContent=disciples.filter(d=>d.status==='active').length;$('discipleApplications').innerHTML=table(apps.map(a=>{const actionable=['submitted','resubmitted','needs_info'].includes(a.status);return `<tr><td><strong>${esc(a.name||[a.legalFirstName,a.legalLastName].filter(Boolean).join(' '))}</strong><div class="muted">${esc(a.applicationReference)}</div></td><td>${esc(a.market||'')}</td><td><span class="status ${esc(a.status)}">${esc(a.status)}</span>${a.duplicateRisk?'<div class="attention-text">Duplicate risk</div>':''}</td><td>${a.submittedAt?new Date(a.submittedAt).toLocaleDateString():'—'}</td><td>${actionable?`<div class="inline-actions"><button class="btn small primary" onclick="discipleStatus('${a.id}','approved')">Approve</button><button class="btn small" onclick="discipleStatus('${a.id}','needs_info')">Need Info</button><button class="btn small danger" onclick="discipleStatus('${a.id}','rejected')">Reject</button></div>`:'—'}</td></tr>`}),['Applicant','Market','Status','Submitted','Actions']);$('disciplesTable').innerHTML=`<p class="muted">Community Bonus: ${data.communityBonusLegalApproved?'Payout enabled':'Legal approval required — payout disabled'}</p>`+table(disciples.map(d=>{const teamCount=teams.filter(t=>t.leaderId===d.id&&!t.endedAt).length,bonus=bonuses.filter(b=>b.leaderId===d.id&&b.status!=='reversed').reduce((n,b)=>n+b.amount,0),emailStatus=d.welcomeEmail?.status||'not sent';return `<tr><td><strong>${esc(d.name)}</strong><div class="muted">${esc(d.email)}</div></td><td>${d.isKingdomLeader?'Kingdom Leader':'Kingdom Disciple'}<div class="muted">${teamCount} direct team</div></td><td><a target="_blank" href="${discipleLink(d)}">${esc(d.handle||'')}</a><div class="muted">Welcome: <span class="status ${esc(emailStatus)}">${esc(emailStatus)}</span></div></td><td>${money(bonus)}</td><td>${kingdomDiscipleActions(d)}</td></tr>`}),['Kingdom Disciple','Role / Team','Personal Link / Email','Community Bonus','Actions'])}
function renderDiscipleFinancials(){if(data.user.role!=='owner')return;const commissions=data.discipleCommissions||[],payouts=data.disciplePayouts||[],disciples=data.disciples||[],name=id=>disciples.find(item=>item.id===id)?.name||id;$('dPendingCommission').textContent=money(commissions.filter(item=>item.status==='pending').reduce((sum,item)=>sum+Number(item.amount||0),0));$('dPaidCommission').textContent=money(commissions.filter(item=>item.status==='paid').reduce((sum,item)=>sum+Number(item.amount||0),0));$('discipleCommissionsTable').innerHTML=table(commissions.map(item=>`<tr><td><strong>${esc(name(item.discipleId))}</strong><div class="muted">Pay to: ${esc(disciples.find(d=>d.id===item.discipleId)?.earningsRecipient||name(item.discipleId))}</div><div class="muted">${esc(item.sourceLabel||item.sourceType||'')}</div></td><td>${money(item.eligibleBase)}</td><td>${Number(item.ratePercent||0)}%</td><td>${money(item.amount)}</td><td><span class="status ${esc(item.status)}">${esc(item.status)}</span><div class="muted">${esc(item.payoutDate||'')}</div></td><td>${item.status==='pending'?`<div class="inline-actions"><button class="btn small primary" onclick="payDiscipleCommission('${item.id}')">Record Paid</button><button class="btn small danger" onclick="reverseDiscipleCommissionAction('${item.id}')">Reverse</button></div>`:item.status==='reversal_required'?`<button class="btn small danger" onclick="reverseDiscipleCommissionAction('${item.id}')">Record Reversal</button>`:'—'}</td></tr>`),['Disciple / Source','Eligible sale','Rate','Commission','Status / Due','Actions']);$('disciplePayoutsTable').innerHTML=table(payouts.map(item=>`<tr><td>${esc(name(item.discipleId))}</td><td>${money(item.amount)}</td><td><span class="status ${esc(item.status)}">${esc(item.status)}</span></td><td>${esc(item.paymentReference||'')}</td><td>${item.createdAt?new Date(item.createdAt).toLocaleString():'—'}</td></tr>`),['Disciple','Amount','Status','Payment reference','Recorded'])}
$('discipleAppFilter').onchange=renderKingdomDisciples;$('discipleSearch').oninput=renderKingdomDisciples;
function showPanel(name){const wasSms=$('panel-sms')?.classList.contains('active');if(name!=='sms')window.KVNSms?.clear();else if(!wasSms&&data?.user?.role==='owner')window.KVNSms?.init({api,user:data.user});document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));document.querySelectorAll('#dashNav button').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));$('panel-'+name)?.classList.add('active')}document.querySelectorAll('#dashNav button').forEach(b=>b.onclick=()=>showPanel(b.dataset.panel));

const defaultTicketSizes=['S','M','L','XL','XXL','XXXL','XXXXL'];
function currentApparel(product={}){const source=product.includedApparel||{},mode=['none','optional','included'].includes(source.mode)?source.mode:source.enabled?'included':'none',sizes=product.type==='apparel'&&product.options?.size?.length?product.options.size:source.sizes?.length?source.sizes:defaultTicketSizes;return {mode,name:source.name||'T-shirt',price:Number(source.price||0),sizes,sizeInventory:source.sizeInventory||{}}}
function productFormHtml(eventId,product={}){const apparel=currentApparel(product),counts=apparel.sizes.map(size=>`${size}=${Number(apparel.sizeInventory[size]??0)}`).join('\n');return `<form id="productForm" class="form-stack"><input type="hidden" name="eventId" value="${eventId}"><input type="hidden" name="productId" value="${product.id||''}"><label>Type<select name="type" id="productType" ${product.id?'disabled':''}><option value="ticket" ${product.type!=='apparel'?'selected':''}>Ticket</option><option value="apparel" ${product.type==='apparel'?'selected':''}>Standalone Apparel</option></select></label><label>Name<input name="name" required value="${esc(product.name||'')}"></label><label>Description<textarea name="description">${esc(product.description||'')}</textarea></label><div class="two-col"><label>Ticket / bundle price ($)<input type="number" step="0.01" min="0" name="price" required value="${(Number(product.price||0)/100).toFixed(2)}"></label><label>Ticket / product inventory<input type="number" min="0" name="inventory" required value="${Number(product.inventory||0)}"></label></div><div id="ticketApparelFields"><label>Ticket apparel mode<select name="apparelMode" id="apparelMode"><option value="none" ${apparel.mode==='none'?'selected':''}>None</option><option value="optional" ${apparel.mode==='optional'?'selected':''}>Optional Add-On</option><option value="included" ${apparel.mode==='included'?'selected':''}>Included With Ticket</option></select></label><div id="activeApparelFields"><label>Apparel name<input name="apparelName" value="${esc(apparel.name)}"></label><label id="optionalPriceField">Optional add-on price ($)<input name="apparelPrice" type="number" min="0" step="0.01" value="${(apparel.price/100).toFixed(2)}"></label><label>Sizes (comma separated)<input name="sizes" value="${esc(apparel.sizes.join(','))}"></label><label>Inventory by size (one SIZE=COUNT per line)<textarea name="sizeInventory">${esc(counts)}</textarea></label><p class="muted" id="apparelModeHelp"></p></div></div><div class="error" id="productError"></div><button class="btn primary">${product.id?'Save Product':'Add Product'}</button></form>`}
function bindProductFields(){const type=$('productType'),mode=$('apparelMode');if(!type||!mode)return;const refresh=()=>{const ticket=type.value==='ticket',active=ticket&&mode.value!=='none';$('ticketApparelFields').hidden=!ticket;$('activeApparelFields').hidden=!active;$('optionalPriceField').hidden=mode.value!=='optional';$('apparelModeHelp').textContent=mode.value==='included'?'The ticket price is the complete pass + T-shirt bundle price. Every pass requires a size.':mode.value==='optional'?'This price is added only for passes whose buyer selects a T-shirt.':''};type.onchange=refresh;mode.onchange=refresh;refresh()}
function openProduct(eventId,product={}){openModal(product.id?'Edit Ticket or Apparel':'Add Ticket or Apparel',productFormHtml(eventId,product));bindProductFields()}
$('addProduct').onclick=()=>openProduct($('builderEvent').value);
window.editProduct=(eventId,productId)=>{const event=data.events.find(item=>item.id===eventId),product=event?.products.find(item=>item.id===productId);if(product)openProduct(eventId,product)};
function renderBuilderProducts(){const event=data?.events.find(item=>item.id===$('builderEvent').value),target=$('builderProducts');if(!target||!event)return;target.innerHTML=event.products.length?event.products.map(product=>`<div class="product-admin-row"><div><strong>${esc(product.name)}</strong><span class="muted">${esc(product.type)} • ${money(product.price)}</span></div><button class="btn small" onclick="editProduct('${event.id}','${product.id}')">Edit</button></div>`).join(''):'<p class="muted">No products yet.</p>'}
function parseSizeInventory(value){const result={};String(value||'').split(/\r?\n|,/).forEach(row=>{const [size,count]=row.split('=').map(item=>item.trim());if(size)result[size]=Math.max(0,Math.trunc(Number(count)||0))});return result}
async function saveConfiguredProduct(event){event.preventDefault();const fields=new FormData(event.target),values=Object.fromEntries(fields),existing=data.events.find(item=>item.id===values.eventId)?.products.find(item=>item.id===values.productId),type=values.type||existing?.type||'ticket',sizes=String(values.sizes||'').split(',').map(size=>size.trim()).filter(Boolean),body={type,name:values.name,description:values.description,price:Math.round(Number(values.price)*100),inventory:Number(values.inventory),options:type==='apparel'?{size:sizes}:undefined};if(type==='ticket')body.includedApparel={mode:values.apparelMode,name:values.apparelName,price:Math.round(Number(values.apparelPrice||0)*100),sizes,sizeInventory:parseSizeInventory(values.sizeInventory),quantityPerTicket:1};try{const url=values.productId?`/api/events/${values.eventId}/products/${values.productId}`:`/api/events/${values.eventId}/products`;await api(url,{method:values.productId?'PUT':'POST',body:JSON.stringify(body)});closeModal();await loadDashboard()}catch(error){$('productError').textContent=error.message}}
$('ownerLogin').onsubmit=async event=>{event.preventDefault();$('loginError').textContent='';try{await api('/api/auth/owner',{method:'POST',body:JSON.stringify({email:$('ownerEmail').value,password:$('ownerPassword').value})});$('ownerPassword').value='';await loadDashboard()}catch(error){$('loginError').textContent=error.message}};
$('forgotPassword').onclick=()=>{$('ownerLogin').hidden=true;$('passwordResetRequest').hidden=false;$('resetEmail').value=$('ownerEmail').value;$('resetRequestStatus').textContent=''};
$('backToLogin').onclick=()=>{$('passwordResetRequest').hidden=true;$('ownerLogin').hidden=false};
$('passwordResetRequest').onsubmit=async event=>{event.preventDefault();const status=$('resetRequestStatus');status.className='muted';status.textContent='Sending…';try{const result=await api('/api/auth/password-reset/request',{method:'POST',body:JSON.stringify({email:$('resetEmail').value})});status.className='success';status.textContent=result.message}catch(error){status.className='error';status.textContent=error.message}};
$('logout').onclick=async()=>{dashboardEpoch++;data=null;analytics=null;$('dashNav').hidden=true;$('whoami').textContent='Not signed in';window.KVNMarketing?.clear();window.KVNSms?.clear();window.KVNAgreements?.clear();window.KVNController?.clear();window.KVNCrm?.clear();window.KVNAccounts?.clear();window.KVNEvents?.clear();window.KVNActivity?.clear();window.KVNBusiness?.clear();closeModal();$('dashboard').hidden=true;$('loginGate').hidden=false;try{await api('/api/auth/logout',{method:'POST'})}catch(error){$('loginError').textContent='Sign-out could not be confirmed. Retry signing out or close this browser.'}};
loadDashboard();

document.querySelectorAll('[data-open-sms]').forEach(button=>button.onclick=()=>showPanel('sms'));
